def remove_stock_fifo(self, name, qty):
    if self.total_quantity(name) < qty:
        raise ValueError("Insufficient stock")
    rem = qty
    while rem > 0:
        take = min(self.items[name][0]['qty'], rem)
        self.items[name][0]['qty'] -= take
        rem -= take
        if self.items[name][0]['qty'] == 0:
            self.items[name].pop(0)
    if name in self.items and not self.items[name]:
        del self.items[name]

